SELECT "TableroSistemaPenal_8"."PAIS" AS "PAIS",   "TableroSistemaPenal_8"."SALIDAS_TEMPRANAS" AS "SALIDAS_TEMPRANAS",   SUM(CAST("TableroSistemaPenal_8"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "TableroSistemaPenal_8"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "TableroSistemaPenal_8" WHERE ("TableroSistemaPenal_8"."SALIDAS_TEMPRANAS" IN ('Aprueba acuerdo reparatorio.', 'Suspensión condicional del procedimiento.')) GROUP BY "TableroSistemaPenal_8"."PAIS",   "TableroSistemaPenal_8"."SALIDAS_TEMPRANAS", "yr_FECHA_ok";
